CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_recepcao_encaminhar_ffa`(
    IN p_id_sessao_usuario BIGINT,
    IN p_id_ffa BIGINT,
    IN p_tipo_destino VARCHAR(50) -- NULL -> TRIAGEM
)
main: BEGIN
    DECLARE v_destino VARCHAR(50);
    DECLARE v_sqlstate VARCHAR(10);
    DECLARE v_errno INT;
    DECLARE v_msg TEXT;

