        RESIGNAL;
    END;

    CALL sp_sessao_assert(p_id_sessao_usuario);

    START TRANSACTION;

    SELECT id_ffa
    INTO v_id_ffa
    FROM senha
    WHERE id_senha = p_id_senha
    LIMIT 1;

    UPDATE senha
    SET
        nao_compareceu = TRUE,
        nao_compareceu_em = NOW(6),
        retorno_utilizado = FALSE,
        id_fluxo_status = 99,
        contexto_fluxo = 'AGUARDANDO_RETORNO',
        atualizado_em = NOW(6)
    WHERE id_senha = p_id_senha
    AND nao_compareceu = FALSE;

    IF v_id_ffa IS NOT NULL THEN

        INSERT INTO workflow_ffa_evento
        (
            id_ffa,
            tipo_evento,
            detalhe,
            id_sessao_usuario,
            criado_em
        )
        VALUES
        (
            v_id_ffa,
            'CHAMADA_NAO_ATENDIDA',
            p_observacao,
            p_id_sessao_usuario,
            NOW(6)
        );

    END IF;

    COMMIT;

END ;;
