       SET ativo = 0,
           encerrado_em = NOW(),
           token = NULL
     WHERE id_sessao_usuario = p_id_sessao_usuario;

    CALL sp_auditoria_evento_registrar(
        p_id_sessao_usuario,
        'sessao_usuario',
        p_id_sessao_usuario,
        'SESSAO_ENCERRADA',
        CONCAT('Motivo: ', COALESCE(p_motivo,'(n/a)')),
        v_id_usuario,
        'sessao_usuario',
        v_id_usuario
    );
END ;;
